/* v6: one lifecycle, authenticated requests, delta map sync and grouped controls. */
let sessionGeneration=0;
let csrf='', mapVersion='', pollBusy=false, pollHandles=[], gameConfig={}, selectedStock='';
const cheatWarning='Cheating is unethical and unfair to other players. Every use is recorded in the audit log.';
function safeImageUrl(value){try{const u=new URL(value,location.origin);return ['http:','https:'].includes(u.protocol)?u.href:''}catch{return ''}}
const sharedAudio=new Audio();sharedAudio.loop=true;sharedAudio.preload='none';let musicUrl='';
const ready=fetch('/api/bootstrap',{credentials:'same-origin'}).then(r=>{if(!r.ok)throw new Error('Game configuration unavailable');return r.json()}).then(c=>{csrf=c.csrf;gameConfig=c;Object.assign(IDEO,c.ideologies);return c});
api=async function(method,path,data){
  const generation=sessionGeneration;
  try{await ready;
  if(method==='POST'&&['/api/admin/give_money','/api/admin/give_resource','/api/admin/give_territory'].includes(path)){
    if(!confirm(cheatWarning+'\nConfirm this host action?'))return {error:'Cancelled'};data={...data,confirm:true};
  }
  const options={method,credentials:'same-origin',headers:{'Content-Type':'application/json','X-WC-CSRF':csrf},body:method==='POST'?JSON.stringify(data||{}):undefined};let r=await fetch(path,options);if(r.status===404&&path.startsWith('/api/ideas'))return {error:'Ideas are not available on this server yet. The host needs to restart the updated game server, then reload this page.'};let result=await r.json();if(r.status===403&&result.error?.startsWith('Refresh the page')){csrf=(await fetch('/api/bootstrap',{credentials:'same-origin'}).then(r=>r.json())).csrf;options.headers['X-WC-CSRF']=csrf;r=await fetch(path,options);result=await r.json()}if(generation!==sessionGeneration)return {error:'Session changed; please retry.'};if(!result||(!r.ok&&!result.error))return {error:'Server returned an unexpected response ('+r.status+'). Please try again.'};if(r.status===401&&currentUser&&path!=='/api/login'){sessionGeneration++;stopPolling();document.body.classList.remove('is-admin');closeProfile();closeAdmin();closeGiftModal();closeCommunityDialog();currentUser=null;document.getElementById('auth-overlay').style.display='flex';document.getElementById('game-screen').style.display='none'}return result}
  catch{return {error:'Connection interrupted. Please try again.'}}
};
function card(title,content){return `<section class="v4-card"><h3>${esc(title)}</h3>${content}</section>`}
function control(label,id,type='text',value=''){return `<label>${esc(label)}<input class="form-input" id="${id}" type="${type}" value="${esc(String(value))}"/></label>`}
async function act(path,data){const r=await api('POST',path,data);toast(r.error||r.message||'Saved',r.error?'error':'success');if(!r.error)await refreshUser();return r}
function addNavigation(id,label,render){
  const tabs=document.querySelector('.sidebar-tabs');let b=document.createElement('button');b.className='stab';b.dataset.panel=id;b.textContent=label;b.onclick=()=>showPanel(id);tabs.appendChild(b);
  const panel=document.createElement('div');panel.id='panel-'+id;panel.className='panel-content';panel.innerHTML=`<div id="${id}-content"></div>`;document.getElementById('sidebar').appendChild(panel);
  PANELS[id]={c:id+'-content',f:render};
}
function installScrollButtons(){
  document.querySelectorAll('.sidebar-tabs').forEach(el=>{
    if(el.dataset.arrows)return;el.dataset.arrows='1';const wrapper=document.createElement('div');wrapper.className='scroll-controls';el.parentNode.insertBefore(wrapper,el);wrapper.appendChild(el);
    for(const [label,dir] of [['‹',-1],['›',1]]){const b=document.createElement('button');b.className='scroll-arrow';b.textContent=label;b.title=dir<0?'Scroll left; hold to continue':'Scroll right; hold to continue';b.setAttribute('aria-label',dir<0?'Scroll menus left':'Scroll menus right');wrapper.appendChild(b);let timer;
      const scroll=()=>el.scrollBy({left:dir*110,behavior:'smooth'});b.onclick=scroll;b.onpointerdown=e=>{b.setPointerCapture(e.pointerId);scroll();timer=setInterval(scroll,180)};for(const event of ['pointerup','pointercancel','lostpointercapture'])b.addEventListener(event,()=>clearInterval(timer));}
  });
}
refreshTerritories=async function(){
  const r=await api('GET','/api/map/sync'+(mapVersion?'?since='+encodeURIComponent(mapVersion):''));if(r.error)return;
  if(r.reset){territories={};for(const k of Object.keys(tlayers)){map.removeLayer(tlayers[k]);delete tlayers[k]}}
  for(const k of r.removed||[]){delete territories[k];if(tlayers[k]){map.removeLayer(tlayers[k]);delete tlayers[k]}}
  for(const t of r.changed||[]){t.color=currentUser?.display_faction_colors!==false&&currentUser?.display_faction_colors!==0?(t.faction_color||t.base_color):t.base_color;const previous=territories[t.grid_key];for(const flag of ['coastal','water','weather'])if(previous?.[flag]!==undefined)t[flag]=previous[flag];if(t.owner_id)t.water=false;territories[t.grid_key]=t;if(tlayers[t.grid_key]){map.removeLayer(tlayers[t.grid_key]);delete tlayers[t.grid_key]}}
  mapVersion=r.version;if(r.reset||r.changed?.length||r.removed?.length)renderTerritories();
};
function stopPolling(){sharedAudio.pause();hideWinScreen();for(const t of pollHandles)clearInterval(t);pollHandles=[];clearInterval(refreshTimer);clearInterval(spectatorTimer)}
async function startSession(user){
  sessionGeneration++;pollBusy=false;selectedKey=null;myAlliances=[];chatLastId={global:0,faction:0};chatCh='global';selectedStock='';seenNotifIds.clear();notifPopupQueue=[];notifShowing=false;document.getElementById('notif-container').replaceChildren();
  await ready;stopPolling();currentUser=user;document.body.classList.toggle('is-admin',!!user?.is_admin);mapVersion='';territories={};tlayers={};if(map){map.remove();map=null;hoverRect=null}
  document.getElementById('auth-overlay').style.display='none';document.getElementById('game-screen').style.display='flex';initMap();map.invalidateSize();
  const [buildings,research]=await Promise.all([api('GET','/api/buildings'),api('GET','/api/research')]);if(!buildings.error)BLD=buildings;if(research.tree)Object.assign(RESEARCH_TREE,research.tree);
  if(user){await refreshUser();if(!currentUser)return false}else updateNavbarGuest();await refreshTerritories();await refreshOnline();drawFallout();await checkGameStatus();updateHud();
  await loadLandGeoJSON();
  pollHandles.push(setInterval(async()=>{if(document.hidden||pollBusy)return;pollBusy=true;try{
    if(currentUser)await refreshUser();await refreshTerritories();await refreshOnline();await checkGameStatus();pollAnnouncements();updateHud();
    if(currentUser){pollNotifications();pollChat();await refreshMusic()}else await api('POST','/api/spectate',{});await drawEva();
  }finally{pollBusy=false}},12000));
  pollHandles.push(setInterval(()=>{if(!document.hidden)drawFallout()},60000));
  if(user){await refreshMusic();const c=await api('GET','/api/changelog');if(c.show)showTextModal('What changed — '+c.version,c.text,async()=>{await api('POST','/api/changelog/seen',{})},'Don’t show again until the next update')}
  else api('POST','/api/spectate',{});
}
startGame=startSession;startSpectatorMode=()=>startSession(null);
doRegister=async function(){const username=document.getElementById('rg-user').value.trim(),password=document.getElementById('rg-pass').value;const r=await api('POST','/api/register',{username,password});if(r.error){document.getElementById('auth-msg').textContent=r.error;return}
  showTextModal('Save your one-time recovery code',r.recovery_code+'\n\nKeep this private. It replaces the old recovery PIN.',async()=>{const l=await api('POST','/api/login',{username,password});if(l.error)return toast(l.error,'error');startGame(l.user)},'I saved the code');
};
function showTextModal(title,text,done,label='Close'){
  document.getElementById('v6-dialog')?.remove();const ov=document.createElement('div');ov.id='v6-dialog';ov.className='v6-overlay';ov.innerHTML=`<div class="v6-dialog"><h2>${esc(title)}</h2><pre>${esc(text)}</pre><button class="btn btn-primary">${esc(label)}</button></div>`;ov.querySelector('button').onclick=async()=>{if(done)await done();ov.remove()};document.body.appendChild(ov);
}
async function refreshMusic(){const r=await api('GET','/api/music');if(r.error)return;if(r.url!==musicUrl){musicUrl=r.url;if(r.url)sharedAudio.src=r.url;else{sharedAudio.pause();sharedAudio.removeAttribute('src');sharedAudio.load()}}sharedAudio.volume=currentUser?.music_volume??.25;sharedAudio.muted=!!currentUser?.music_muted;if(musicUrl&&!sharedAudio.muted)sharedAudio.play().catch(()=>{})}
document.addEventListener('pointerdown',()=>{if(musicUrl&&!sharedAudio.muted)sharedAudio.play().catch(()=>{})});
async function savePreference(key,value){const r=await act('/api/profile/preferences',{[key]:value});if(!r.error){if(key==='display_faction_colors'){mapVersion='';await refreshTerritories()}await refreshMusic()}}
function buildSettings(){const u=currentUser,el=document.getElementById('settings-content');if(!u){el.textContent='Log in to change settings';return}
  const toggle=(k,label)=>`<label class="setting"><input type="checkbox" ${u[k]?'checked':''} onchange="savePreference('${k}',this.checked)"/> ${label}</label>`;
  el.innerHTML=card('Map & faction sharing',toggle('display_faction_colors','Display faction colours on the map')+toggle('share_boats','Allow faction members to use my boats')+toggle('share_planes','Allow faction members to use my planes')+'<p class="v4-sub">Sharing is off by default. Your vehicles remain yours when you leave a faction.</p>')+card('Shared music',toggle('music_muted','Mute music')+`<label>Volume <input type="range" min="0" max="1" step=".05" value="${u.music_volume}" onchange="savePreference('music_volume',+this.value)"/></label>`)+card('Account recovery','<p>Generate a new one-time recovery code. This replaces your previous code.</p>'+control('Current password','recovery-password','password')+'<button class="btn btn-primary" onclick="newRecovery()">Generate recovery code</button>');
}
async function newRecovery(){const r=await act('/api/profile/recovery',{password:document.getElementById('recovery-password').value});if(r.recovery_code)showTextModal('Save this private code',r.recovery_code)}
const oldEmpire=buildEmpire;buildEmpire=async function(){await oldEmpire();const el=document.getElementById('empire-content');if(!currentUser||!el)return;const u=currentUser;
  const religion=card('Religion',`<p class="v4-sub">Change once per 24 hours. ${u.religion_cooldown?'Ready in '+Math.ceil(u.religion_cooldown/3600)+' hours.':''}</p>`+Object.entries(gameConfig.religions).map(([id,r])=>`<div class="v4-row"><span class="grow"><b>${esc(r.name)}</b><p class="v4-sub">${esc(r.desc)}</p></span><button class="btn btn-ghost" ${u.religion===id||u.religion_cooldown?'disabled':''} onclick="empAct('/api/religion/set',{id:'${id}'})">${u.religion===id?'Active':'Adopt'}</button></div>`).join(''));
  el.insertAdjacentHTML('afterbegin',religion);const w=await api('GET','/api/wonders');const wonderCard=[...el.querySelectorAll('.v4-card')].find(c=>c.textContent.includes('Wonders'));if(wonderCard&&Array.isArray(w))wonderCard.innerHTML=`<h3>🏛 Country wonders</h3><p class="v4-sub">Build once for your entire country. No tile selection needed.</p>`+w.map(x=>`<div class="v4-row"><span class="grow"><b>${esc(x.name)}</b><p class="v4-sub">${esc(x.desc)} · ${fmtCost(x.cost)}</p></span>${x.owned?'<span class="chip good">Owned</span>':`<button class="btn btn-primary" ${!x.can_build?'disabled':''} onclick="empAct('/api/wonders/buy',{key:'${x.key}'})">🏛 Build</button>`}</div>`).join('');
  const eva=await api('GET','/api/eva');if(u.wonders?.some(key=>['eva_00','eva_01','eva_02'].includes(key)))el.insertAdjacentHTML('beforeend',card('EVA — cosmetic only',(eva.images||[]).map(i=>`<figure><img class="eva-image" src="${i.url}" alt="${esc(i.name)}"/><figcaption>${esc(i.unit)} · ${esc(i.name)} · no stat effects</figcaption><button class="btn btn-ghost" onclick="deployEva('${i.url.split('/').pop()}')">Place on selected owned tile</button></figure>`).join('')||'<p>No EVA portraits are available yet. The host can add images.</p>'));
};
function wheel(selected){return `<div class="colour-wheel" role="group" aria-label="Eight exclusive faction colours">${gameConfig.faction_colors.map((c,i)=>`<button title="Faction colour ${i+1}" style="--segment:${i};--colour:${c}" class="${selected===i?'selected':''}" onclick="pickFactionColour(${i})"><span>${i+1}</span></button>`).join('')}</div><input id="chosen-colour" type="hidden" value="${selected??0}"/>`}
function pickFactionColour(slot){document.getElementById('chosen-colour').value=slot;document.querySelectorAll('.colour-wheel button').forEach((b,i)=>b.classList.toggle('selected',i===slot))}
const oldFaction=buildFaction;buildFaction=async function(){await oldFaction();const el=document.getElementById('faction-content');if(!el||!currentUser)return;const page=await api('GET','/api/faction/page');if(page.faction){const f=page.faction;el.insertAdjacentHTML('afterbegin',card('Faction overview',`<p><b>${esc(f.name)}</b> · Treasury ${fmtN(f.treasury)} · shared boats ${f.shared_boats??0} · shared planes ${f.shared_planes??0}</p>`));if(f.is_leader)el.insertAdjacentHTML('afterbegin',card('Exclusive faction colour',wheel(f.color_slot)+'<button class="btn btn-primary" onclick="setFactionColour()">Save colour</button>'))}else el.insertAdjacentHTML('afterbegin',card('Choose a founding colour',wheel(0)+'<p class="v4-sub">Eight factions maximum. Taken segments cannot be selected on the server.</p>'));
};
async function setFactionColour(){await act('/api/faction/settings',{color_slot:+document.getElementById('chosen-colour').value});buildFaction()}
const oldApi=api;api=async function(method,path,data){if(['/api/faction/create','/api/faction/settings'].includes(path)&&document.getElementById('chosen-colour'))data={...data,color_slot:+document.getElementById('chosen-colour').value};return oldApi(method,path,data)};
async function buildStocks(){const el=document.getElementById('stocks-content');if(!currentUser){el.textContent='Log in to invest';return}const r=await api('GET','/api/stocks'+(selectedStock?'?symbol='+encodeURIComponent(selectedStock):''));if(r.error){el.textContent=r.error;return}
  el.innerHTML=card('Stock exchange',`<p class="v4-sub">Prices can rise or fall. ${r.fee*100}% fee on each trade. Updated every ${r.interval/60} minutes. No investment in your own country or faction.</p><select id="stock-symbol" class="form-input" onchange="selectedStock=this.value;buildStocks()"><option value="">Choose an investment</option>${r.assets.map(a=>`<option value="${a.symbol}" ${a.symbol===selectedStock?'selected':''}>${esc(a.name||a.symbol)} · ${a.kind} · ${a.price.toFixed(2)}${!a.investable?' · buy restricted':''}</option>`).join('')}</select>`+control('Shares','stock-quantity','number',1)+'<div class="v4-row"><button class="btn btn-primary" onclick="tradeStock(\'buy\')">Buy</button><button class="btn btn-ghost" onclick="tradeStock(\'sell\')">Sell</button></div><canvas id="stock-chart" width="380" height="160" aria-label="Price history chart"></canvas>')+card('Portfolio',r.portfolio.map(h=>`<p>${esc(h.symbol)} · ${h.quantity} shares · value ${h.value.toFixed(2)} · paid ${h.cost_basis.toFixed(2)}</p>`).join('')||'<p>No holdings yet.</p>');
  const canvas=document.getElementById('stock-chart'),ctx=canvas.getContext('2d'),points=r.history;if(points.length){const lo=Math.min(...points.map(p=>p.price)),hi=Math.max(...points.map(p=>p.price)),range=hi-lo||1;ctx.strokeStyle='#60a5fa';ctx.lineWidth=2;ctx.beginPath();points.forEach((p,i)=>{const x=20+i*340/Math.max(1,points.length-1),y=130-(p.price-lo)*100/range;i?ctx.lineTo(x,y):ctx.moveTo(x,y)});ctx.stroke();ctx.fillStyle='#ddd';ctx.fillText('Low '+lo.toFixed(2)+' / High '+hi.toFixed(2),20,153)}
}
async function tradeStock(side){await act('/api/stocks/trade',{symbol:document.getElementById('stock-symbol').value,quantity:+document.getElementById('stock-quantity').value,side});buildStocks()}
async function buildHost(){const el=document.getElementById('host-content');if(!currentUser?.is_admin){el.textContent='Host access required';return}const [players,stats,audit]=await Promise.all([api('GET','/api/admin/users'),api('GET','/api/admin/requests?sort='+requesterSort),api('GET','/api/admin/audit')]);
  el.innerHTML=card('Host controls',`<select id="host-player" class="form-input">${(Array.isArray(players)?players:[]).map(p=>`<option value="${p.id}">${esc(p.username)}</option>`).join('')}</select><div class="host-actions"><button class="btn btn-ghost" onclick="hostAction('kick')">Kick session</button><button class="btn btn-danger" onclick="hostBan(true)">Ban</button><button class="btn btn-ghost" onclick="hostBan(false)">Unban</button><button class="btn btn-ghost" onclick="hostMute()">Mute</button><button class="btn btn-danger" onclick="hostIdeaBan(true)">Block ideas</button><button class="btn btn-ghost" onclick="hostIdeaBan(false)">Allow ideas</button><button class="btn btn-ghost" onclick="hostRecovery()">Reset code</button><button class="btn btn-ghost" onclick="hostAction('faction')">Set faction</button><button class="btn btn-ghost" onclick="hostAction('tile')">Assign selected tile</button><button class="btn btn-danger" onclick="hostAction('delete_tile')">Delete selected tile</button><button class="btn btn-danger" onclick="openResourceReset(hostUid())">Reset resources</button><button class="btn btn-danger" onclick="hostAction('reset')">Reset player</button><button class="btn btn-danger" onclick="openCheats()">Cheat menu</button></div><p class="v4-sub">Tile actions use the currently selected map cell.</p><button class="btn btn-ghost" onclick="legacyAdmin()">More host tools</button>`)+card('Private request tracking',`<label>Sort <select id="request-sort" onchange="buildHost()"><option value="requests">Top requesters</option><option value="username">Username</option><option value="ip">Client IP</option><option value="last_seen">Last seen</option></select></label><div class="table-scroll"><table><thead><tr><th>Player</th><th>Client IP</th><th>Peer IP</th><th>Requests</th></tr></thead><tbody>${(stats.users||stats.clients||[]).map(s=>`<tr><td>${esc(s.username||'Guest')}</td><td>${esc(s.ip)}</td><td>${esc(s.peer_ip)}</td><td>${s.requests}</td></tr>`).join('')}</tbody></table></div>`)+card('Rate limits','<p class="v4-sub">0 means unlimited. Limits stay off until you set a positive value.</p>'+control('Requests per IP / minute','rate-requests','number',stats.limits?.requests??0)+control('Account attempts per IP / minute','rate-auth','number',stats.limits?.auth??0)+control('Seconds between chat messages (0 = unlimited)','rate-chat','number',stats.limits?.chat??0)+control('Seconds between stock trades (0 = unlimited)','rate-trades','number',stats.limits?.trades??0)+'<button class="btn btn-primary" onclick="saveRates()">Save limits</button>')+card('Music for all players','<p class="v4-sub">One MP3, maximum 15 MB. Replacing it updates every player.</p><input type="file" id="music-upload" accept="audio/mpeg,.mp3"/><button class="btn btn-primary" onclick="uploadMusic()">Upload / replace MP3</button><button class="btn btn-danger" onclick="removeMusic()">Remove shared music</button>')+card('Audit log',`<div class="table-scroll"><table><tr><th>Time</th><th>Actor</th><th>Action</th><th>Target</th></tr>${(audit.entries||[]).map(a=>`<tr><td>${new Date(a.ts*1000).toLocaleString()}</td><td>${esc(a.actor||'Host')}</td><td title="${esc(a.details)}">${esc(a.action)}</td><td>${a.target_id||''}</td></tr>`).join('')}</table></div>`);
}
const legacyAdmin=openAdmin;
openAdmin=async function(){
  if(!currentUser?.is_admin)return toast('Admin access required','error');
  await legacyAdmin();
  adminTab({target:document.querySelector('.admin-tabs .atab')},'players');
  await showLanAddresses();
};
async function showLanAddresses(){
  const el=document.getElementById('admin-lan-address');
  if(!el)return;
  const result=await api('GET','/api/admin/network');
  if(result.error){el.textContent=result.error;return}
  el.innerHTML='<b>Join from the same network</b>'+((result.urls||[]).map(url=>`<div><a href="${esc(url)}" style="color:var(--accent2)">${esc(url)}</a></div>`).join('')||'<p>No LAN address detected. Check that the host is connected to Wi-Fi or Ethernet.</p>')+`<p class="v4-sub">${esc(result.note)}</p>`+(result.local_only?'<p>The server is listening only on this computer. Set HOST=0.0.0.0 and restart to allow LAN players.</p>':'');
}
function installHostAdminTab(){
  // Keep the original dashboard and all of its controls as the main admin UI.
  // Install legacy additions before scroll buttons wrap the tab bar.
  injectAdmin();
  const tabs=document.querySelector('.admin-tabs');
  if(!tabs||document.getElementById('admin-host'))return;
  const address=document.createElement('div');address.id='admin-lan-address';address.className='v4-card';
  address.textContent='Open the dashboard to check the LAN address.';tabs.parentElement.insertBefore(address,tabs);
  const button=document.createElement('button');button.className='atab';button.textContent='Host tools';
  button.onclick=event=>adminTab(event,'host');tabs.appendChild(button);
  const panel=document.createElement('div');panel.id='admin-host';panel.className='admin-panel';
  panel.innerHTML='<div id="host-content"></div>';tabs.parentElement.appendChild(panel);
}
const previousAdminTab=adminTab;
adminTab=function(event,id){previousAdminTab(event,id);if(id==='host')buildHost()};
function hostUid(){return +document.getElementById('host-player').value}
async function hostBan(ban){await act('/api/admin/ban',{user_id:hostUid(),ban});buildHost()}
async function hostMute(){const minutes=prompt('Mute for how many minutes?', '10');if(minutes!==null)await act('/api/admin/mute',{user_id:hostUid(),minutes:+minutes})}
async function hostRecovery(){const r=await act('/api/admin/recovery',{user_id:hostUid()});if(r.reset_code)showTextModal('Share this reset code privately',r.reset_code+'\nExpires in one hour; usable once.')}
async function hostAction(action){let d={user_id:hostUid(),action,grid_key:selectedKey};if(action==='faction'){const fid=prompt('Faction ID (0 to leave)', '0');if(fid===null)return;d.faction_id=+fid}if(!confirm('Confirm '+action+' for the selected player?'))return;d.confirm=true;await act('/api/admin/player',d);buildHost();mapVersion='';await refreshTerritories()}
function openCheats(){if(!confirm(cheatWarning+'\nOpen the cheat menu?'))return;const uid=hostUid();document.getElementById('v6-dialog')?.remove();const ov=document.createElement('div');ov.id='v6-dialog';ov.className='v6-overlay';ov.innerHTML=`<div class="v6-dialog"><h2>Host cheat menu</h2><p class="cheat-warning">${cheatWarning}</p><select id="cheat-resource"><option>money</option><option>food</option><option>wood</option><option>metal</option><option>oil</option><option>steel</option><option>uranium</option><option>gems</option><option>army</option><option>boats</option><option>planes</option></select>${control('Amount','cheat-amount','number',100)}<div class="host-actions"><button class="btn btn-danger" onclick="cheat(${uid},'give_money')">Give money</button><button class="btn btn-danger" onclick="cheat(${uid},'give_resource')">Give resource</button><button class="btn btn-danger" onclick="cheat(${uid},'resources')">Set resource</button><button class="btn btn-danger" onclick="cheat(${uid},'spawn')">Spawn units</button><button class="btn btn-danger" onclick="cheat(${uid},'instant_build')">Instant build</button></div><p class="cheat-warning">Cheating is unethical and unfair to other players. Every action requires confirmation.</p><button class="btn btn-ghost" onclick="document.getElementById('v6-dialog').remove()">Close</button></div>`;document.body.appendChild(ov)}
async function cheat(uid,action){if(!confirm(cheatWarning+'\nConfirm '+action+'?'))return;const d={user_id:uid,action,confirm:true,resource:document.getElementById('cheat-resource').value,amount:+document.getElementById('cheat-amount').value,grid_key:selectedKey};if(action==='instant_build'){d.type=prompt('Building key (e.g. farm, airport, port)','farm');if(!d.type)return}await act('/api/admin/player',d)}
async function saveRates(){await act('/api/admin/rate_limits',{requests:+document.getElementById('rate-requests').value,auth:+document.getElementById('rate-auth').value,chat:+document.getElementById('rate-chat').value,trades:+document.getElementById('rate-trades').value})}
async function uploadMusic(){const file=document.getElementById('music-upload').files[0];if(!file)return toast('Choose an MP3','error');const form=new FormData();form.append('file',file);const r=await fetch('/api/admin/music',{method:'POST',headers:{'X-WC-CSRF':csrf},body:form}).then(r=>r.json());toast(r.error||r.message,r.error?'error':'success');await refreshMusic()}
async function removeMusic(){
  if(!confirm('Remove the shared music and stop it for all players?'))return;
  const result=await act('/api/admin/music/remove',{});
  if(!result.error)await refreshMusic();
}
/* Mobile moves the existing panel instead of creating duplicate element IDs. */
let movedPanel=null;
