    for(const f of collection.features){const [left,bottom,right,top]=f.properties.bounds;for(let x=Math.floor(left/5);x<=Math.floor(right/5);x++)for(let y=Math.floor(bottom/5);y<=Math.floor(top/5);y++){const key=x+','+y;if(!islandBuckets.has(key))islandBuckets.set(key,[]);islandBuckets.get(key).push(f)}}
